{
  "name": "@gfn-cis/opencode-temp-sanitize",
  "version": "0.3.0",
  "description": "OpenCode 2 plugin that gives each project its own temporary directory",
  "type": "module",
  "main": "index.js",
  "files": [
    "index.js",
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "vitest run",
    "coverage": "vitest run --coverage",
    "lint": "biome check .",
    "lint:fix": "biome check --write .",
    "knip": "knip"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tmp"
  ],
  "author": "GFN-CIS",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/GFN-CIS/opencode-temp-sanitize.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=22.12.0",
    "opencode": ">=2.0.0"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.6.6",
    "@vitest/coverage-v8": "^5.1.0",
    "knip": "^6.44.2",
    "vitest": "^5.1.0"
  }
}
